function heap_queue_largest(nums, n) {
  // Helper function to perform heapify
  function heapify(arr, i, n) {
    let largest = i; // Initialize largest as root
    let left = 2 * i + 1; // Left child
    let right = 2 * i + 2; // Right child

    // If left child is larger than root
    if (left < n && arr[left] > arr[largest]) {
      largest = left;
    }

    // If right child is larger than largest so far
    if (right < n && arr[right] > arr[largest]) {
      largest = right;
    }

    // If largest is not root
    if (largest !== i) {
      [arr[i], arr[largest]] = [arr[largest], arr[i]]; // Swap
      heapify(arr, largest, n); // Recursively heapify the affected sub-tree
    }
  }

  // Main function to perform heap sort
  function heap_sort(arr, n) {
    // Build heap (rearrange array into a max heap)
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
      heapify(arr, i, n);
    }

    // Extract elements one by one from heap
    for (let i = n - 1; i >= 0; i--) {
      [arr[0], arr[i]] = [arr[i], arr[0]]; // Swap
      heapify(arr, 0, i); // Heapify the reduced heap
    }
  }

  // Sort the array using heap sort
  heap_sort(nums, nums.length);

  // Return the n largest integers in descending order
  return nums.slice(-n);
}

