  function heapify(arr, n, i) {
    let largest = i;
    let left = 2 * i + 1;
    let right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
      largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
      largest = right;
    }

    if (largest !== i) {
      swap(arr, i, largest);
      heapify(arr, n, largest);
    }
  }

  // Build a max heap
  for (let i = Math.floor(nums.length / 2) - 1; i >= 0; i--) {
    heapify(nums, nums.length, i);
  }

  // Extract the n largest elements
  let largestElements = [];
  for (let i = 0; i < n; i++) {
    largestElements.push(nums[0]);
    swap(nums, 0, nums.length - 1 - i);
    heapify(nums, nums.length - 1 - i, 0);
  }

  return largestElements;
}

function k_smallest_pairs(nums1, nums2, k) {
  const minHeap = new MinHeap();
  const visited = new Set();

  for (const num1 of nums1) {
    for (const num2 of nums2) {
      if (!visited.has(`${num1},${num2}`)) {
        minHeap.push([num1, num2, 0]);
        visited.add(`${num1},${num2}`);
      }
    }
  }

  const result = [];

  while (result.length < k && !minHeap.isEmpty()) {
    const [num1, num2, index] = minHeap.pop();
    result.push([num1, num2]);

    if (index < nums2.length - 1) {
      minHeap.push([num1, nums2[index + 1], index + 1]);
      visited.add(`${num1},${nums2[index + 1]}`);
    }
  }

  return result;
}

function k_smallest_pairs(nums1, nums2, k) {
  // Sort both arrays to facilitate the use of a min-heap
  nums1.sort((a, b) => a - b);
  nums2.sort((a, b) => a - b);

  // Initialize a min-heap with the first element from each array
  const minHeap = new MinHeap();
  minHeap.push([nums1[0], nums2[0], 0, 0]);

  // Initialize an array to store the k smallest pairs
  const result = [];

  // Continue until we have k pairs or the heap is empty
  while (result.length < k && !minHeap.isEmpty()) {
    const [num1, num2, i, j] = minHeap.pop();

    // Add the current pair to the result
    result.push([num1, num2]);

    // If there is a next element in nums1, push it to the heap
    if (i + 1 < nums1.length) {
      minHeap.push([nums1[i + 1], num2, i + 1, j]);
    }

    // If there is a next element in nums2, push it to the heap
    if (j + 1 < nums2.length) {
      minHeap.push([num1, nums2[j + 1], i, j + 1]);
    }
  }

  return result;
}

