  const dp = Array.from({ length: n }, () => Array.from({ length: n }, () => 0));

  // Fill the dp array
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i <= j && a[i] < a[j] && i <= index && j > index) {
        dp[i][j] = Math.max(dp[i][j], dp[i][k] + a[j]);
      }
    }
  }

  // Find the maximum sum of increasing subsequence including the kth element
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      if (a[i] < a[j] && i <= index && j > index) {
