  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) return true;
  }
  return false;
}

function separate_paren_groups(paren_string){
    const result = [];
    let currentGroup = "";
    let depth = 0;

    for (const char of paren_string.replace(/\s+/g, '')) {
        if (char === '(') {
            depth++;
            currentGroup += char;
        } else if (char === ')') {
            depth--;
            currentGroup += char;
            if (depth === 0) {
                result.push(currentGroup);
                currentGroup = "";
            }
        }
    }

    return result;
}

