function eulerian_num(n, m) {
  if (n === 0 && m === 0) return 1;
  if (n < m) return 0;
  return (n + m) * eulerian_num(n - 1, m - 1) - m * eulerian_num(n - 1, m);
}

function eulerian_num(n, m) {
  if (m > n) return 0;
  if (m === 0) return 1;
  if (m === 1) return n;
  return (n - m) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m);
}

