function max_sum(arr) {
  let n = arr.length;
  let dp = new Array(n).fill(0);
  let dp_desc = new Array(n).fill(0);

  // Calculate the maximum sum of increasing subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp[j] + arr[i] > dp[i]) {
        dp[i] = dp[j] + arr[i];
      }
    }
  }

  // Calculate the maximum sum of decreasing subsequence
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dp_desc[j] + arr[i] > dp_desc[i]) {
        dp_desc[i] = dp_desc[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
  }

  return max_sum;
}

function max_sum(arr) {
  const n = arr.length;
  const dp1 = new Array(n).fill(0);
  const dp2 = new Array(n).fill(0);

  // Calculate the maximum sum of increasing subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp1[i] = Math.max(dp1[i], dp1[j] + arr[i]);
      }
    }
    dp1[i] = Math.max(dp1[i], arr[i]);
  }

  // Calculate the maximum sum of decreasing subsequence
  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j > i; j--) {
      if (arr[i] > arr[j]) {
        dp2[i] = Math.max(dp2[i], dp2[j] + arr[i]);
      }
    }
    dp2[i] = Math.max(dp2[i], arr[i]);
  }

  // Find the maximum sum of bitonic subsequence
  let maxSum = 0;
  for (let i = 0; i < n; i++) {
    maxSum = Math.max(maxSum, dp1[i] + dp2[i] - arr[i]);
  }

  return maxSum;
}

