function bell_Number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - 1 - j];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

function bell_Number(n){
    if (n === 0) return 1;
    let bell = [1];
    for (let i = 1; i <= n; i++) {
        let nextBell = bell[i - 1].slice(0, i) + [1].concat(bell[i - 1].slice(i));
        bell.push(nextBell);
    }
    return bell[n];
}

function all_Bits_Set_In_The_Given_Range(n, l, r){
  // Convert the number to a binary string
  const binaryString = n.toString(2);

  // Iterate through the range l to r
  for(let i = l; i <= r; i++){
    // Check if the i-th bit is unset (0)
    if(binaryString[i] === '0'){
      return false;
    }
  }

  // If all bits are set, return true
  return true;
}

function all_Bits_Set_In_The_Given_Range(n, l, r){
