function toggle_middle_bits(n) {
    // Clear the first and last bits
    let mask = ~(1 << 31) | (1 << 0); // 1111111111111111111111111111111100000000
    n = n ^ mask;

    // Toggle the middle bits
    mask = ~(1 << 15) | ~(1 << 16); // 1111111111111111111111111111111100000000
    n = n ^ mask;

    return n;
}

