function change_base(x, base) {
  if (base < 2 || base > 9) {
    throw new Error("Base must be between 2 and 9.");
  }

  let result = "";
  while (x > 0) {
    let remainder = x % base;
    result = remainder.toString() + result;
    x = Math.floor(x / base);
  }

  return result;
}

