function magic_square_test(my_matrix){
  // Check if the matrix is a magic square
  const n = my_matrix.length;
  if (n === 0) return false;

  // Calculate the sum of the first row
  const sum = my_matrix[0].reduce((acc, val) => acc + val, 0);

  // Check if all rows have the same sum
  for (let i = 1; i < n; i++) {
    if (my_matrix[i].reduce((acc, val) => acc + val, 0) !== sum) {
      return false;
    }
  }

  // Check if all columns have the same sum
  for (let i = 0; i < n; i++) {
    let colSum = 0;
    for (let j = 0; j < n; j++) {
      colSum += my_matrix[j][i];
    }
    if (colSum !== sum) {
