function max_sum_increasing_subseq(a, n, index, k){
    // Initialize a DP table to store the maximum sum of increasing subsequence including the kth element
    let dp = new Array(n).fill(0);
    dp[index] = a[index]; // The sum of the current element is the element itself

    // Iterate through the array starting from the next element
    for (let i = index + 1; i < n; i++) {
        // Check if the current element is greater than the previous element and within the range k > i
        if (a[i] > a[index] && i > k) {
            // Update the DP table with the maximum sum including the current element
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }
    }

    // Find the maximum sum of increasing subsequence including the kth element
    let maxSum = 0;
    for (let i = index + 1; i < n; i++) {
        maxSum = Math.max(maxSum, dp[i]);
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a DP array to store the maximum sum of increasing subsequence up to each index
  const dp = new Array(n).fill(0);
  dp[index] = a[index]; // The sum of the subsequence ending at the current index

  // Iterate through the array to find the maximum sum of increasing subsequence up to each index
  for (let i = index + 1; i < n; i++) {
    // Check if the current element is greater than the previous element and is part of the increasing subsequence
    if (a[i] > a[index] && dp[i] < dp[index] + a[i]) {
      dp[i] = dp[index] + a[i];
    }
  }

  // Find the maximum sum of increasing subsequence up to the given index
  let max_sum = 0;
  for (let i = 0; i <= index; i++) {
    max_sum = Math.max(max_sum, dp[i]);
  }

  // Check if the kth element is part of the increasing subsequence
  if (k <= index && k < n && a[k] > a[index]) {
    max_sum = Math.max(max_sum, dp[k]);
  }

  return max_sum;
}

