function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathLength = Infinity;
    const minPathValues = [];

    function dfs(row, col, steps) {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPathValues = [...path];
            }
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dr, dc] of directions) {
            dfs(row + dr, col + dc, steps + 1);
        }

        path.pop();
        visited[row][col] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    return minPathValues;
}

