function encode(message) {
  const vowels = 'aeiou';
  const vowelsMap = {
    a: 'c', e: 'g', i: 'k', o: 'q', u: 'w'
  };

  return message.split('').map(char => {
    if (!vowels.includes(char.toLowerCase())) {
      return char;
    }

    const nextVowel = vowelsMap[char.toLowerCase()];
    const nextChar = nextVowel === 'c' ? 'e' : nextVowel === 'g' ? 'i' : nextVowel === 'k' ? 'o' : nextVowel === 'q' ? 'u' : 'c';
