function rgb_to_hsv(r, g, b) {
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    const rc = (max - r) / delta;
    const gc = (max - g) / delta;
    const bc = (max - b) / delta;

    if (r === max) {
      h = bc - gc;
    } else if (g === max) {
      h = 2 + rc - bc;
    } else {
      h = 4 + gc - rc;
    }

    h /= 6;
    if (h < 0) h += 1;
  }

  return { h, s, v };
}

function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to [0, 1]
    r /= 255;
    g /= 255;
    b /= 255;

    // Find the maximum and minimum values in the RGB array
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the value (V)
    let v = max;

    // Calculate the saturation (S)
    let s = max === 0 ? 0 : (max - min) / max;

    // Calculate the hue (H)
    let h;
    if (max === min) {
        h = 0; // All colors are the same
    } else {
        switch (max) {
            case r:
                h = (g - b) / (max - min) % 6;
                break;
            case g:
                h = (b - r) / (max - min) + 2;
                break;
            case b:
                h = (r - g) / (max - min) + 4;
                break;
        }
        h /= 6;
    }

    // Convert hue from radians to degrees
    h *= 360;

    return [h, s, v];
}

