function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n + 1).fill(0);
    let max_sum = 0;

    for (let i = 0; i < n; i++) {
        dp[i] = a[i];
        for (let j = 0; j < i; j++) {
            if (a[i] > a[j] && i > j) {
                dp[i] = Math.max(dp[i], dp[j] + a[i]);
            }
        }
        if (index < i && a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }
        if (index < i && k > i && a[i] > a[k]) {
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
        }
        max_sum = Math.max(max_sum, dp[i]);
    }

    return max_sum;
}

