function find_combinations(test_list){
  const result = [];
  const dfs = (index, currentSum, currentCombination) => {
    if (currentSum === 0) {
      result.push([...currentCombination]);
      return;
    }
    for (let i = index; i < test_list.length; i++) {
      if (test_list[i] <= currentSum) {
        currentCombination.push(test_list[i]);
        dfs(i + 1, currentSum - test_list[i], currentCombination);
        currentCombination.pop();
      }
    }
  };
  dfs(0, 0, []);
  return result;
}

function find_combinations(test_list){
  let combinations = [];
  let currentCombination = [];
  let sum = 0;

  function backtrack(start) {
    if (sum === test_list.length) {
      combinations.push([...currentCombination]);
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      currentCombination.push(test_list[i]);
      sum += test_list[i];
      backtrack(i + 1);
      currentCombination.pop();
      sum -= test_list[i];
    }
  }

  backtrack(0);
  return combinations;
}

