function large_product(nums1, nums2, N) {
  // Sort both arrays in descending order
  nums1.sort((a, b) => b - a);
  nums2.sort((a, b) => b - a);

  // Initialize an array to store the largest products
  const largestProducts = [];

  // Iterate through the first array up to N elements
  for (let i = 0; i < N; i++) {
    // Iterate through the second array up to N elements
    for (let j = 0; j < N; j++) {
      // Calculate the product of the selected elements
      const product = nums1[i] * nums2[j];
      // Add the product to the largestProducts array
      largestProducts.push(product);
    }
  }

  // Sort the largestProducts array in descending order
  largestProducts.sort((a, b) => b - a);

  // Return the first N elements of the largestProducts array
  return largestProducts.slice(0, N);
}

