function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

  function dfs(row, col, path, steps) {
    if (steps === k) {
      return path;
    }

    const neighbors = [];
    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
        neighbors.push([newRow, newCol]);
      }
    }

    let minPath = Infinity;
    for (const [newRow, newCol] of neighbors) {
      const newPath = [...path, grid[newRow][newCol]];
      const newPathLength = newPath.length;
      const newPathLexicalLessThanCurrentPath = newPathLength < k || newPath[newPathLength - 1] < minPath;
      if (newPathLexicalLessThanCurrentPath) {
        const newPathResult = dfs(newRow, newCol, newPath, steps + 1);
        if (newPathResult !== Infinity) {
          minPath = Math.min(minPath, newPathResult);
        }
      }
    }

    return minPath;
  }

  let minPathResult = Infinity;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const result = dfs(i, j, [grid[i][j]], 1);
      if (result !== Infinity) {
        minPathResult = Math.min(minPathResult, result);
      }
    }
  }

  return minPathResult;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
  let visited = new Array(N).fill().map(() => new Array(N).fill(false));
  let minPath = [];
  let minPathLength = Infinity;

  function dfs(row, col, pathLength) {
    if (pathLength === k) {
      if (pathLength < minPathLength || (pathLength === minPathLength && path.join('') < minPath.join(''))) {
        minPath = path.slice();
        minPathLength = pathLength;
      }
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        dfs(newRow, newCol, path.concat(grid[newRow][newCol]));
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, [grid[i][j]]);
      visited[i][j] = false;
    }
  }

  return minPath;
}

