  // To check if a number is octagonal, we need to solve for n in the equation: 3n^2 - 2n - 2n^2 + 2n = n
  // This simplifies to: 3n^2 - 2n = n, which further simplifies to: 3n^2 - 3n = 0
  // Factoring out n gives us: n(3n - 3) = 0
  // So, n = 0 or 3n - 3 = 0, which means n = 0 or n = 1
  return n === 0 || n === 1;
