function find_combinations(test_list){
  let result = [];
  let sum = 0;
  let current_combination = [];

  function backtrack(start, target) {
    if (sum === target) {
      result.push([...current_combination]);
      return;
    }
    if (sum > target) {
      return;
    }
    for (let i = start; i < test_list.length; i++) {
      current_combination.push(test_list[i]);
      sum += test_list[i];
      backtrack(i + 1, target);
      current_combination.pop();
      sum -= test_list[i];
    }
  }

  backtrack(0, 0);
  return result;
}

function find_combinations(test_list) {
    const result = [];
    const helper = (index, currentSum, currentCombination) => {
        if (currentSum === 0) {
            result.push(currentCombination.slice());
            return;
        }
        if (index >= test_list.length || currentSum < 0) {
            return;
        }
        currentCombination.push(test_list[index]);
        helper(index + 1, currentSum - test_list[index], currentCombination);
        currentCombination.pop();
        helper(index + 1, currentSum, currentCombination);
    };
    helper(0, 0, []);
    return result;
}

