function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Set();
    const path = [];

    function dfs(row, col, steps, path) {
        if (steps === k) {
            path.push(grid[row][col]);
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited.has(`${row},${col}`)) {
            return;
        }

        visited.add(`${row},${col}`);
        path.push(grid[row][col]);

        for (const [dr, dc] of directions) {
            dfs(row + dr, col + dc, steps + 1, path);
        }

        path.pop();
        visited.delete(`${row},${col}`);
    }

    let minPath = Infinity;
    let minPathCells = [];

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
            const currentPath = path.slice();
            currentPath.sort((a, b) => a - b);
            if (currentPath.length === k && currentPath.join(',') < minPath) {
                minPath = currentPath.join(',');
                minPathCells = currentPath;
            }
            path.pop();
        }
    }

    return minPathCells;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left

    const visited = new Set();
    const queue = [[0, 0, 0]]; // [row, col, steps]

    while (queue.length > 0) {
        const [row, col, steps] = queue.shift();

        if (steps === k) {
            return grid[row][col];
        }

        if (visited.has(`${row},${col}`)) continue;

        visited.add(`${row},${col}`);

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                queue.push([newRow, newCol, steps + 1]);
            }
        }
    }

    return null; // In case no path is found
}

