function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r = r / 255;
  g = g / 255;
  b = b / 255;

  // Find the maximum and minimum values in the RGB array
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  // Calculate the saturation
  const saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue
  let hue;
  if (saturation === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (g - b) / (max - min) % 6;
  } else if (max === g) {
    hue = (b - r) / (max - min) + 2;
  } else {
    hue = (r - g) / (max - min) + 4;
  }

  // Convert the hue to degrees
  hue = hue * 60;

  // Calculate the value
  const value = max;

  return { hue, saturation, value };
}

