    const digits = Array.from(String(n), Number);
    let found = false;

    // Iterate through the digits to find the first digit that is smaller than the digit immediately after it
    for (let i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit in the remaining part of the array that is greater than digits[i]
            let j = i + 1;
            while (j < digits.length && digits[j] <= digits[i]) {
                j++;
            }

            // Swap the found digits
            [digits[i], digits[j - 1]] = [digits[j - 1], digits[i]];

            // Sort the remaining part of the array in ascending order
            digits.splice(i + 1).sort((a, b) => a - b);

            // Convert the array of digits back to a number and return it
            return parseInt(digits.join(''), 10);
        }
    }

    // If no such number can be formed, return -1
    return -1;
}

