function rearrange_bigger(n) {
  const digits = Array.from(String(n));
  const len = digits.length;

  // Find the first digit from the right that is smaller than the digit immediately to its right
  for (let i = len - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right of i that is greater than digits[i]
      let j = len - 1;
      while (digits[j] <= digits[i]) {
        j--;
      }

      // Swap digits[i] and digits[j]
      [digits[i], digits[j]] = [digits[j], digits[i]];

      // Sort the digits to the right of i in ascending order
      for (let k = i + 1; k < len; k++) {
        for (let l = k + 1; l < len; l++) {
          if (digits[l] < digits[k]) {
            [digits[k], digits[l]] = [digits[l], digits[k]];
          }
        }
      }

      // Convert the array of digits back to a number
      return parseInt(digits.join(''));
    }
  }

  // If no such number exists, return -1
  return -1;
}

function rearrange_bigger(n){
    // Convert number to string to easily manipulate digits
    let digits = n.toString().split('');

    // Sort the digits in descending order to get the largest possible number
    digits.sort((a, b) => b - a);

    // Find the index of the first digit that is smaller than the digit next to it
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible permutation
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit greater than the digit at index i
    let j = digits.length - 1;
    while (j >= 0 && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the digits at index i and j
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the remaining digits in ascending order
    digits.splice(i + 1).sort((a, b) => a - b);

    // Join the digits back into a number and return
    return parseInt(digits.join(''));
}

