        if (i < 0 || i >= N || j < 0 || j >= N || visited.has(`${i},${j}`)) {
            return;
        }

        visited.add(`${i},${j}`);
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            dfs(i + dx, j + dy, steps + 1, path);
        }

        path.pop();
        visited.delete(`${i},${j}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    minPath.sort((a, b) => a - b);
    return minPath;
}

