function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    if (r === max) {
      h = (g - b) / delta;
    } else if (g === max) {
      h = 2 + (b - r) / delta;
    } else {
      h = 4 + (r - g) / delta;
    }

    h /= 6;
    if (h < 0) h += 1;
  }

  return { h, s, v };
}

function rgb_to_hsv(r, g, b){
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    if (delta === 0) {
        return [0, 0, max];
    }

    let h;
    if (max === r) {
        h = (g - b) / delta % 6;
    } else if (max === g) {
        h = (b - r) / delta + 2;
    } else if (max === b) {
        h = (r - g) / delta + 4;
    }

    let s = delta / max;
    let v = max;

    return [h * 360, s, v];
}

