  if (n <= 1) return n; // Base case: the maximum sum for 1 or 0 is the number itself

  // Recursive case: calculate the maximum sum by considering the three possible divisions
  const maxSum = Math.max(
    get_max_sum(n / 2) + get_max_sum(n / 3) + get_max_sum(n / 4) + get_max_sum(n / 5),
    n
  );

