}

function get_max_sum(n) {
  if (n === 1) return 1;

  const memo = new Map();

  function helper(n) {
    if (memo.has(n)) return memo.get(n);

    const maxSum = Math.max(
      helper(n / 2) + helper(n / 3) + helper(n / 4) + helper(n / 5),
      n
    );

    memo.set(n, maxSum);
    return maxSum;
  }

  return helper(n);
}

