            for (let j = digits.length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    [digits[i], digits[j]] = [digits[j], digits[i]];
                    digits.splice(i + 1);
                    digits.sort((a, b) => a - b);
                    return parseInt(digits.join(''));
                }
            }
        }
    }
    return -1; // No bigger number can be formed
}

