    let minPath = [];
    let visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    let directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    function dfs(row, col, path, count) {
        if (count === k) {
            minPath = path.slice();
            return;
        }

        for (let dir of directions) {
            let newRow = row + dir[0];
            let newCol = col + dir[1];

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, [...path, grid[newRow][newCol]], count + 1);
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]], 1);
            visited[i][j] = false;
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
    const path = [];
    let minPathLength = Infinity;

    function dfs(row, col, steps) {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPath = [...path];
            }
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                dfs(newRow, newCol, steps + 1);
            }
        }

        path.pop();
        visited[row][col] = false;
    }

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            dfs(i, j, 0);
        }
    }

    return minPath;
}

