    let end = array.length - 1;

    while (start <= end) {
        let mid = Math.floor((start + end) / 2);

        // Check if the mid element is the smallest missing number
        if (array[mid] !== mid + 1) {
            return mid + 1;
        }

        // If the mid element is equal to its index, the missing number is in the right half
        if (array[mid] === mid) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }

    // If no missing number is found, the array is complete and the next number is the smallest missing
