  }).join('');
}

function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    s = delta / v;

    if (r === max) {
      h = (g - b) / delta;
    } else if (g === max) {
      h = 2 + (b - r) / delta;
    } else {
      h = 4 + (r - g) / delta;
    }

    h *= 60;
    if (h < 0) {
      h += 360;
    }
  }

  return { h, s, v };
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values of RGB
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the value
  let value = max;

  // Calculate the hue
  let hue;
  if (max === min) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / (max - min))) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / (max - min))) + 120;
  } else if (max === b) {
    hue = (60 * ((r - g) / (max - min))) + 240;
  }

  // Return the hsv color as an array [hue, saturation, value]
  return [hue, saturation, value];
}

function rearrange_bigger(n) {
  const digits = n.toString().split('');
  const length = digits.length;

  for (let i = length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          break;
        }
      }
      digits.splice(i + 1);
      digits.sort((a, b) => a - b);
      return parseInt(digits.join(''));
    }
  }
  return -1; // Return -1 if no bigger number can be formed
}

function rearrange_bigger(n){
    let digits = n.toString().split('');
    let sortedDigits = digits.sort((a, b) => b - a);
    let i = digits.length - 1;

    while (i > 0 && digits[i] <= digits[i - 1]) {
        i--;
    }

    if (i === 0) {
        return -1; // No bigger number can be formed
    }

    let j = digits.length - 1;
    while (digits[j] <= digits[i - 1]) {
        j--;
    }

    [digits[i - 1], digits[j]] = [digits[j], digits[i - 1]];

    digits.splice(i, digits.length - i);

    sortedDigits.splice(i, 0, digits[i - 1]);

    return parseInt(digits.join(''));
}

