function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (x, y, pathLength, path) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPath = [...path];
            }
            return;
        }

        if (pathLength > minPathLength) return;

        visited[x][y] = true;

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, pathLength + 1, [...path, grid[nx][ny]]);
            }
        }

        visited[x][y] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

function minPath(grid, k) {
