  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathValue = Infinity;

  const dfs = (i, j, steps) => {
    if (steps === k) {
      if (path.length < minPathValue || (path.length === minPathValue && path.join(',') < minPathValue.join(','))) {
        minPathValue = path.join(',');
        minPath = [...path];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const x = i + dx;
      const y = j + dy;
      if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
        visited[x][y] = true;
        path.push(grid[x][y]);
        dfs(x, y, steps + 1);
        path.pop();
        visited[x][y] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1);
    }
  }

