    for (let i = 0; i <= n - len; i++) {
      let j = i + len - 1;
      dp[i][j] = Math.max(arr[i] * dp[i+1][j], arr[j] * dp[i][j-1], arr[i] * arr[j] * dp[i+1][j-1]);
    }
  }

  return dp[0][n-1];
}

