  }

  // Use bitwise operations to check if the number can be represented as a sum of powers of 2
  while (n > 0) {
    // If the least significant bit is set, it means the number can be represented as a sum of powers of 2
    if (n & 1) {
      return true;
    }
    // Right shift the number by 1 to check the next bit
    n >>= 1;
  }

