function find_combinations(test_list) {
    // Helper function to find combinations recursively
    function find_combinations_recursive(test_list, current_sum, start, combinations) {
        if (current_sum === 0) {
            combinations.push([]);
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            if (test_list[i] > current_sum) {
                break;
            }
            const new_combinations = find_combinations_recursive(test_list, current_sum - test_list[i], i + 1, combinations);
            for (const combo of new_combinations) {
                combo.push(test_list[i]);
                combinations.push(combo);
            }
        }
        return combinations;
    }

    // Start the recursion with the initial parameters
    return find_combinations_recursive(test_list, 0, 0, []);
}

function find_combinations(test_list){
  let result = [];
  function combine(arr, sum, index) {
    if (sum === 0) {
      result.push([...arr]);
      return;
    }
    for (let i = index; i < arr.length; i++) {
      if (arr[i] <= sum) {
        arr.push(arr[i]);
        combine(arr, sum - arr[i], i);
        arr.pop();
      }
    }
  }
  combine(test_list, 0, 0);
  return result;
}
